<path>frontend/src/views/notes/FolderSidebar.tsx</path>
<content>import React, { useState, useEffect } from 'react';
import {
  Box,
  List,
  ListItemButton,
  ListItemText,
  Typography,
  IconButton,
  Chip,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import FolderIcon from '@mui/icons-material/Folder';
import InboxIcon from '@mui/icons-material/Inbox';
import Button from '../../components/design-system/Button';
import TextField from '../../components/design-system/TextField';
import Dialog from '../../components/shared/Dialog';
import InlineConfirmButton from '../../components/shared/InlineConfirmButton';
import { foldersApi } from '../../services/api';
import { Folder, Note } from '../../types';

interface FolderSidebarProps {
  notes: Note[];
  selectedFolderId: string | null;
  onFolderSelect: (folderId: string | null) => void;
}

const FolderSidebar: React.FC<FolderSidebarProps> = ({
  notes,
  selectedFolderId,
  onFolderSelect,
}) => {
  const [folders, setFolders] = useState<Folder[]>([]);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingFolder, setEditingFolder] = useState<Folder | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    color: '#808080',
  });

  useEffect(() => {
    loadFolders();
  }, []);

  const loadFolders = async () => {
    try {
      const data = await foldersApi.getAll();
      setFolders(data);
    } catch (error) {
      console.error('Failed to load folders:', error);
    }
  };

  const getFolderNoteCount = (folderId: string | null) => {
    return notes.filter((note) => note.folder_id === folderId).length;
  };

  const handleCreateFolder = async () => {
    try {
      await foldersApi.create(formData);
      setCreateDialogOpen(false);
      setFormData({ name: '', description: '', color: '#808080' });
      loadFolders();
    } catch (error) {
      console.error('Failed to create folder:', error);
    }
  };

  const handleEditFolder = async () => {
    if (!editingFolder) return;
    try {
      await foldersApi.update(editingFolder.id, formData);
      setEditDialogOpen(false);
      setEditingFolder(null);
      setFormData({ name: '', description: '', color: '#808080' });
      loadFolders();
    } catch (error) {
      console.error('Failed to update folder:', error);
    }
  };

  const handleDeleteFolder = async (folderId: string) => {
    try {
      await foldersApi.delete(folderId);
      if (selectedFolderId === folderId) {
        onFolderSelect(null);
      }
      loadFolders();
    } catch (error) {
      console.error('Failed to delete folder:', error);
    }
  };

  const openEditDialog = (folder: Folder) => {
    setEditingFolder(folder);
    setFormData({
      name: folder.name,
      description: folder.description || '',
      color: folder.color,
    });
    setEditDialogOpen(true);
  };

  return (
    <Box sx={{ width: 250, borderRight: 1, borderColor: 'divider', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Typography variant="h6">Folders</Typography>
        <IconButton size="small" onClick={() => setCreateDialogOpen(true)}>
          <AddIcon />
        </IconButton>
      </Box>

      <List sx={{ flex: 1, overflow: 'auto' }}>
        <ListItemButton
          selected={selectedFolderId === null}
          onClick={() => onFolderSelect(null)}
        >
          <InboxIcon sx={{ mr: 2, color: 'text.secondary' }} />
          <ListItemText primary="Unorganized" />
          <Chip label={getFolderNoteCount(null)} size="small" />
        </ListItemButton>

        {folders.map((folder) => (
          <ListItemButton
            key={folder.id}
            selected={selectedFolderId === folder.id}
            onClick={() => onFolderSelect(folder.id)}
          >
            <FolderIcon sx={{ mr: 2, color: folder.color }} />
            <ListItemText primary={folder.name} />
            <Chip label={getFolderNoteCount(folder.id)} size="small" sx={{ mr: 0.5 }} />
            <IconButton size="small" onClick={(e) => { e.stopPropagation(); openEditDialog(folder); }}>
              <EditIcon fontSize="small" />
            </IconButton>
            <InlineConfirmButton onConfirm={() => handleDeleteFolder(folder.id)} />
          </ListItemButton>
        ))}
      </List>

      <Dialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        title="Create Folder"
        onConfirm={handleCreateFolder}
      >
        <TextField
          label="Name"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          autoFocus
        />
        <TextField
          label="Description"
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          multiline
          rows={2}
        />
        <TextField
          label="Color"
          type="color"
          value={formData.color}
          onChange={(e) => setFormData({ ...formData, color: e.target.value })}
        />
      </Dialog>

      <Dialog
        open={editDialogOpen}
        onClose={() => setEditDialogOpen(false)}
        title="Edit Folder"
        onConfirm={handleEditFolder}
      >
        <TextField
          label="Name"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          autoFocus
        />
        <TextField
          label="Description"
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          multiline
          rows={2}
        />
        <TextField
          label="Color"
          type="color"
          value={formData.color}
          onChange={(e) => setFormData({ ...formData, color: e.target.value })}
        />
      </Dialog>
    </Box>
  );
};

export default FolderSidebar;
</content>
